<?php

declare(strict_types=1);
$root=dirname(__DIR__);require_once $root.'/scripts/lib/trusted-update.php';$args=[];foreach(array_slice($argv,1) as $a){if(str_starts_with($a,'--import='))$args['import']=substr($a,9);elseif($a==='--status')$args['status']=true;elseif($a==='--lineage')$args['lineage']=true;elseif($a==='--rotate')$args['rotate']=true;elseif($a==='--revoke')$args['revoke']=true;elseif(str_starts_with($a,'--reason='))$args['reason']=substr($a,9);elseif(str_starts_with($a,'--confirm='))$args['confirm']=substr($a,10);}
if(isset($args['status'])){$a=nexoraUpdateTrustReadJson(nexoraUpdateTrustAnchorPath($root));$e=nexoraValidateRecipientTrustAnchor($a);fwrite(STDOUT,json_encode(['status'=>$e===[]?'pass':'blocked','anchor'=>$a,'errors'=>$e],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL);exit($e===[]?0:1);}if(isset($args['lineage'])){$r=nexoraVerifyRecipientTrustLineage($root);fwrite(STDOUT,json_encode(['status'=>$r['ok']?'pass':'blocked',...$r],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL);exit($r['ok']?0:1);}if(isset($args['revoke'])){if(($args['confirm']??'')!=='REVOKE'){fwrite(STDERR,"[Nexora Update Trust] REFUSED — revocation requires --confirm=REVOKE.\n");exit(2);}try{$a=nexoraRevokeRecipientTrustAnchor($root,(string)($args['reason']??'operator revocation'));fwrite(STDOUT,"[Nexora Update Trust] PASS — recipient trust anchor revoked for key {$a['key_id']}.\n");exit(0);}catch(Throwable $e){fwrite(STDERR,"[Nexora Update Trust] FAIL — {$e->getMessage()}\n");exit(1);}}if(!isset($args['import'])){fwrite(STDERR,"Usage: php scripts/trusted-update-trust-anchor.php --import=<trusted-anchor.json> [--rotate --confirm=ROTATE] | --revoke --confirm=REVOKE [--reason=...] | --status | --lineage\n");exit(2);}if(isset($args['rotate'])&&($args['confirm']??'')!=='ROTATE'){fwrite(STDERR,"[Nexora Update Trust] REFUSED — rotation requires --confirm=ROTATE.\n");exit(2);}try{$a=nexoraImportRecipientTrustAnchor($root,(string)$args['import'],isset($args['rotate']));fwrite(STDOUT,"[Nexora Update Trust] PASS — recipient trust anchor active for key {$a['key_id']}.\n");exit(0);}catch(Throwable $e){fwrite(STDERR,"[Nexora Update Trust] FAIL — {$e->getMessage()}\n");exit(1);}
